      es: ["La población de Siraha es de unos 70.000 habitantes.", "Siraha se encuentra a 70 metros de altitud.", "La superficie útil para la caña de azúcar es de 5.000 hectáreas.", "La estación de Siraha forma parte del tramo de 30 km hacia Jaynagar.", "La ciudad tiene una superficie de 20 kilómetros cuadrados.", "La producción de yute es de 2.000 toneladas anuales."],
