      fr: ["La population de Siraha est d'environ 70 000 habitants.", "Siraha est située à 70 mètres d'altitude.", "La surface cultivée pour la canne à sucre est de 5 000 hectares.", "La gare de Siraha fait partie du tronçon de 30 km vers Jaynagar.", "La ville s'étend sur 20 kilomètres carrés.", "La production de jute s'élève à 2 000 tonnes par an."],
