    descriptionAdvanced: {
      de: "Inaruwa ist das administrative Hauptquartier des Distrikts Sunsari in der Provinz Koshi im Südosten Nepals. Die Stadt liegt strategisch günstig am Mahendra Highway, der wichtigsten Ost-West-Verbindung des Landes, was sie zu einem bedeutenden Logistik- und Handelszentrum macht. Geografisch befindet sich Inaruwa in der fruchtbaren Terai-Ebene, unweit des mächtigen Koshi-Flusses. Eine der wichtigsten Attraktionen in der Nähe ist das Koshi Tappu Wildlife Reserve, das für seine Wasserbüffel und eine Vielzahl von Zugvögeln bekannt ist. Die Wirtschaft der Stadt basiert hauptsächlich auf der Landwirtschaft, wobei der Handel mit Reis und Jute eine zentrale Rolle spielt. Inaruwa dient auch als Bildungszentrum für die Region mit mehreren Schulen und Colleges. Die kulturelle Vielfalt ist groß, wobei Gemeinschaften wie die Tharu, Yadav und Muslime friedlich zusammenleben und die lokale Identität prägen.",
      hu: "Inaruwa a Sunsari körzet közigazgatási központja a Koshi tartományban, Nepál délkeleti részén. A város stratégiai elhelyezkedése a Mahendra főút mentén, amely az ország legfontosabb kelet-nyugati útvonala, jelentős logisztikai és kereskedelmi csomóponttá teszi. Földrajzilag Inaruwa a termékeny Terai-alföldön található, nem messze a hatalmas Koshi-folyótól. A környék egyik legfontosabb látnivalója a közeli Koshi Tappu Vadrezervátum, amely a vadon élő vízibivalyairól és számos vándormadárfajáról híres. A város gazdasága elsősorban a mezőgazdaságra épül, ahol a rizs- és jutakereskedelem központi szerepet játszik. Inaruwa a régió oktatási központjaként is szolgál, számos iskolával és főiskolával rendelkezik. A kulturális sokszínűség jelentős, a tharu, yadav és muszlim közösségek békés együttélése formálja a helyi identitást.",
      ro: "Inaruwa este sediul administrativ al districtului Sunsari din provincia Koshi, situată în sud-estul Nepalului. Orașul este amplasat strategic pe autostrada Mahendra, principala rută est-vest a țării, ceea ce îl transformă într-un centru logistic și comercial important. Geografic, Inaruwa se află în câmpia fertilă Terai, nu departe de puternicul râu Koshi. Una dintre cele mai importante atracții din apropiere este Rezervația de Faună Koshi Tappu, renumită pentru bivolii săi sălbatici și o mare varietate de păsări migratoare. Economia orașului se bazează în principal pe agricultură, comerțul cu orez și iută jucând un rol central. Inaruwa servește, de asemenea, ca centru educațional pentru regiune, având mai multe școli și colegii. Diversitatea culturală este semnificativă, comunitățile Tharu, Yadav și musulmane conviețuind pașnic și modelând identitatea locală.",
      en: "Inaruwa serves as the administrative headquarters of the Sunsari District in Koshi Province, located in southeastern Nepal. The city is strategically positioned along the Mahendra Highway, the nation's primary east-west arterial road, making it a vital logistics and commercial hub. Geographically, Inaruwa lies within the fertile Terai plains, in close proximity to the massive Koshi River. A major nearby attraction is the Koshi Tappu Wildlife Reserve, which is globally recognized for its population of wild water buffaloes and diverse migratory bird species. The local economy is predominantly agricultural, with the trade of rice and jute playing a central role in regional commerce. Inaruwa also acts as an educational center for the district, hosting several schools and colleges. Its cultural landscape is diverse, with Tharu, Yadav, and Muslim communities contributing to a rich and harmonious local social fabric.",
      es: "Inaruwa es una ciudad del distrito de Sunsari, en el Terai oriental de Nepal. Tiene una población de unas 50.000 personas. Inaruwa es un centro agrícola centrado en el arroz, el maíz y las verduras. La ciudad está cerca del río Koshi, uno de los ríos más grandes de Nepal, y es conocida por la Reserva de Vida Silvestre Koshi Tappu. Inaruwa cuenta con un mercado regional y pequeñas industrias. La población está formada principalmente por grupos Maithili y Tharu. La ciudad dispone de escuelas y un hospital. El clima es subtropical. Inaruwa es un nodo importante para el transporte en la región.",
      pt: "Inaruwa é uma cidade no distrito de Sunsari, no Terai oriental do Nepal. Tem uma população de cerca de 50.000 habitantes. Inaruwa é um centro agrícola com foco no arroz, milho e vegetais. A cidade fica perto do rio Koshi, um dos maiores rios do Nepal, e é conhecida pela Reserva de Vida Selvagem Koshi Tappu. Inaruwa tem um mercado regional e pequenas indústrias. A população é composta principalmente por grupos Maithili e Tharu. A cidade tem escolas e um hospital. O clima é subtropical. Inaruwa é um nó importante para o transporte na região.",
      fr: "Inaruwa est une ville du district de Sunsari dans le Terai oriental du Népal. Elle compte une population d'environ 50 000 habitants. Inaruwa est un centre agricole axé sur le riz, le maïs et les légumes. La ville se trouve à proximité de la rivière Koshi, l'une des plus grandes rivières du Népal, et est connue pour la réserve de vie sauvage de Koshi Tappu. Inaruwa possède un marché régional et de petites industries. La population est principalement composée de groupes Maithili et Tharu. La ville dispose d'écoles et d'un hôpital. Le climat est subtropical. Inaruwa est un carrefour important pour les transports dans la région.",
    },
