      hu: ["A Sunsari körzeti hivatalok székhelye", "A Mahendra főút, Nepál legfontosabb útja mentén fekszik", "Inaruwa önkormányzatát hivatalosan 1991-ben alapították", "A Koshi Tappu Vadrezervátum közelsége (kb. 15 km)", "A juta- és rizskereskedelem fontos központja", "Lakossága tharu és más etnikai csoportok keverékéből áll"],
