      es: ["La población de Inaruwa es de unos 50.000 habitantes.", "Inaruwa está a 100 metros de altitud.", "El río Koshi tiene 730 kilómetros de largo.", "La Reserva de Vida Silvestre Koshi Tappu tiene 175 kilómetros cuadrados.", "La ciudad tiene una superficie de 15 kilómetros cuadrados.", "La superficie de cultivo de arroz es de 10.000 hectáreas."],
      pt: ["A população de Inaruwa é de cerca de 50.000 habitantes.", "Inaruwa situa-se a 100 metros de altitude.", "O rio Koshi tem 730 quilómetros de comprimento.", "A Reserva de Vida Selvagem Koshi Tappu estende-se por 175 quilómetros quadrados.", "A cidade tem uma área de 15 quilómetros quadrados.", "A área de cultivo de arroz é de 10.000 hectares."],
      fr: ["La population d'Inaruwa est d'environ 50 000 habitants.", "Inaruwa est située à 100 mètres d'altitude.", "La rivière Koshi est longue de 730 kilomètres.", "La réserve de vie sauvage de Koshi Tappu s'étend sur 175 kilomètres carrés.", "La ville a une superficie de 15 kilomètres carrés.", "La surface de culture du riz est de 10 000 hectares."],
