      hu: ["A Bardiya körzet székhelye a Lumbini tartományban", "A nyugati Terai-alföldön fekszik, az indiai határ közelében", "A Bardiya Nemzeti Park egyik legfontosabb kapuja", "Az önkormányzatot 1971-ben alapították", "A Babai-folyó szeli át a Bardiya körzetet", "A gabona- és fakereskedelem fontos gazdasági központja"],
      ro: ["Sediul districtului Bardiya din provincia Lumbini", "Situat în vestul Terai, aproape de granița cu India", "Principala poartă de acces către Parcul Național Bardiya", "Municipalitatea a fost înființată în anul 1971", "Râul Babai traversează districtul Bardiya", "Centru economic pentru comerțul cu cereale și lemn"],
      en: ["Headquarters of the Bardiya District in Lumbini Province", "Located in the western Terai near the border with India", "Main gateway to the renowned Bardiya National Park", "The municipality was established in 1971", "The Babai River flows through the Bardiya District", "A major economic hub for grain and timber trade"],
      es: ["Población de Gulariya: unos 80.000 habitantes (censo de 2021).", "Superficie de la ciudad: 74,2 kilómetros cuadrados.", "Fundada como municipio urbano en 1997.", "Altitud sobre el nivel del mar: 150 metros.", "Distancia a la capital, Katmandú: aprox. 450 kilómetros.", "Número de escuelas: más de 30."],
      pt: ["População de Gulariya: cerca de 80.000 habitantes (censo de 2021).", "Área da cidade: 74,2 quilómetros quadrados.", "Fundada como município urbano em 1997.", "Altitude acima do nível do mar: 150 metros.", "Distância até à capital Catmandu: cerca de 450 quilómetros.", "Número de escolas: mais de 30."],
      fr: ["Population de Gulariya : environ 80 000 habitants (recensement 2021).", "Superficie de la ville : 74,2 kilomètres carrés.", "Fondée en tant que municipalité urbaine en 1997.", "Altitude au-dessus du niveau de la mer : 150 mètres.", "Distance de la capitale Katmandou : environ 450 kilomètres.", "Nombre d'écoles : plus de 30."],
