      es: ["Número de habitantes: 26.000 (estimación)", "Altitud: 70 metros sobre el nivel del mar", "Aeropuerto: Bhadrapur Airport (ICAO: VNBT)", "Distancia a Katmandú: unos 390 kilómetros", "Temperatura media: 24°C", "Principal producto agrícola: arroz y té"],
      pt: ["Número de habitantes: 26.000 (estimativa)", "Altitude: 70 metros acima do nível do mar", "Aeroporto: Bhadrapur Airport (ICAO: VNBT)", "Distância até Catmandu: cerca de 390 quilómetros", "Temperatura média: 24°C", "Principais produtos agrícolas: arroz e chá"],
      fr: ["Nombre d'habitants : 26 000 (estimation)", "Altitude : 70 mètres au-dessus du niveau de la mer", "Aéroport : Bhadrapur Airport (OACI : VNBT)", "Distance de Katmandou : environ 390 kilomètres", "Température moyenne : 24 °C", "Principaux rendements agricoles : riz et thé"],
